const I18N = {};
LORDER.forEach((code, i) => { I18N[code] = {}; for (const k in TR) I18N[code][k] = TR[k][i]; });
let LANG = 'en';
const detectLang = () => { const l = String((typeof navigator !== 'undefined' && navigator.language) || 'en').slice(0, 2).toLowerCase(); return I18N[l] ? l : 'en'; };
const setLang = c => { LANG = I18N[c] ? c : 'en'; return LANG; };
const t = (k, ...a) => {
  let s = (I18N[LANG] && I18N[LANG][k]) ?? I18N.en[k] ?? k;
  a.forEach((v, i) => { s = s.split('{' + i + '}').join(v); });
  return s;
};
